namespace Radivum.Model;

/// <summary>
/// Deterministic finding generated by checks or analysis.
/// </summary>
public sealed record Finding(
    string Code,
    string Severity,
    string Title,
    string Description,
    string Confidence,
    IReadOnlyList<FindingEvidence> Evidence,
    IReadOnlyList<string> Resources)
{
    /// <summary>
    /// Evidence classification for this finding. Version 1 uses configured evidence by default.
    /// </summary>
    public string EvidenceLevel { get; init; } = "Configured";

    /// <summary>
    /// Source classification for this finding, such as Snapshot, Graph, Rule, Trace, or Level2.
    /// </summary>
    public string Source { get; init; } = "Rule";

    /// <summary>
    /// Canonical list of affected Azure resource identifiers.
    /// </summary>
    public IReadOnlyList<string> AffectedResourceIds { get; init; } = Resources;

    /// <summary>
    /// Canonical list of affected graph node identifiers.
    /// </summary>
    public IReadOnlyList<string> AffectedGraphNodeIds { get; init; } = [];

    /// <summary>
    /// Edition that produced this finding. Findings produced by the shared deterministic checks are
    /// tagged <see cref="FindingOrigin.Oss"/>; premium analysis tags its own output
    /// <see cref="FindingOrigin.Pro"/>. Defaulting to <see cref="FindingOrigin.Oss"/> keeps snapshots
    /// written before origin tagging was introduced deserializable.
    /// </summary>
    public FindingOrigin Origin { get; init; } = FindingOrigin.Oss;
}

/// <summary>
/// Evidence entry used to justify a finding.
/// </summary>
public sealed record FindingEvidence(
    string SourceType,
    string SourceId,
    string Description,
    DateTimeOffset? CollectedAt);
